import{_ as s}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as l,X as n,x as a,a as r,t as d}from"./chunks/vendor-vueuse.XPft87tp.js";const b=JSON.parse('{"title":"Vue3 渲染原理","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue3-rendering.md","filePath":"vue/vue3-rendering.md","lastUpdated":1785917016000}'),i={name:"vue/vue3-rendering.md"};function p(t,e,u,c,h,g){return l(),o("div",null,[e[3]||(e[3]=n('<h1 id="vue3-渲染原理" tabindex="-1">Vue3 渲染原理 <a class="header-anchor" href="#vue3-渲染原理" aria-label="Permalink to &quot;Vue3 渲染原理&quot;">​</a></h1><h3 id="编译时-模板-→-render-函数" tabindex="-1">编译时：模板 → render 函数 <a class="header-anchor" href="#编译时-模板-→-render-函数" aria-label="Permalink to &quot;编译时：模板 → render 函数&quot;">​</a></h3><p>开发者编写的 <code>&lt;template&gt;</code> 并不会直接在浏览器中执行。Vue3 会在构建阶段将模板编译成 render 函数，并在编译过程中完成两个关键优化：</p><p><strong>静态提升（Static Hoisting）</strong>：模板中不会变化的节点，比如 <code>&lt;h1&gt;博客标题&lt;/h1&gt;</code> 这类没有插值表达式、动态属性和事件绑定的纯静态内容，会在编译时被提取为常量。组件重新渲染时，不需要重复创建这些节点。</p>',4)),a("p",null,[e[0]||(e[0]=a("strong",null,"Patch Flag（补丁标记）",-1)),e[1]||(e[1]=r("：编译器会为动态节点标记变化类型，告诉运行时“这个节点的哪些部分可能变化”。比如 ")),a("code",null,'<p :class="cls">'+d(t.text)+"</p>",1),e[2]||(e[2]=r(" 会被标记为 CLASS + TEXT。Diff 时只比较这些被标记的部分，静态内容可以直接跳过。"))]),e[4]||(e[4]=n(`<h3 id="运行时-虚拟-dom" tabindex="-1">运行时：虚拟 DOM <a class="header-anchor" href="#运行时-虚拟-dom" aria-label="Permalink to &quot;运行时：虚拟 DOM&quot;">​</a></h3><p>初次渲染时，执行 render 函数生成虚拟 DOM 树，然后调用原生 DOM API 逐一创建真实元素，挂载到 <code>#app</code> 上。</p><p>同时进行依赖收集：当模板里引用了 <code>count.value</code> 时，触发 Proxy 的 get 拦截。Vue3 的依赖收集最小单位是<strong>组件</strong>——不是单个变量，而是一个组件对应一个副作用函数。</p><h3 id="响应式更新-精准触达" tabindex="-1">响应式更新：精准触达 <a class="header-anchor" href="#响应式更新-精准触达" aria-label="Permalink to &quot;响应式更新：精准触达&quot;">​</a></h3><p>当 <code>count.value</code> 改变时，触发 Proxy 的 set 拦截。Vue3 能定位到<strong>依赖该数据的组件</strong>，然后重新执行对应组件的 render 函数，生成一棵新的虚拟 DOM 树。</p><p>新树和旧树进行 Diff，结合编译阶段的 Patch Flag，Vue3 只更新真正变动了的 DOM 节点，静态节点完全跳过。</p><h3 id="渲染流程串联" tabindex="-1">渲染流程串联 <a class="header-anchor" href="#渲染流程串联" aria-label="Permalink to &quot;渲染流程串联&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写模板 → 编译(静态提升+Patch Flag) → render函数 → 虚拟DOM → 真实DOM</span></span>
<span class="line"><span>                                                         ↑</span></span>
<span class="line"><span>响应式数据变化 → set拦截 → 找到依赖组件 → 重新render → Diff → 精准DOM更新</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,8))])}const f=s(i,[["render",p]]);export{b as __pageData,f as default};
